sion:{"zh-CN":"【压抑前奏】","en-US":"[Suppression Prelude]"},inspiration_sd_buildup:{"zh-CN":"【暗中蓄势】","en-US":"[Hidden Buildup]"},inspiration_sd_fourbeats:{"zh-CN":"打脸四拍执行节拍：","en-US":"Catharsis 4-Beat Pacing:"},inspiration_sd_upgradepath:{"zh-CN":"升级路径：","en-US":"Escalation Path: "},inspiration_sd_antifatigue:{"zh-CN":"防疲劳提示：","en-US":"Anti-Fatigue Tip: "},inspiration_sd_btn_copy:{"zh-CN":"复制本套爽点模型","en-US":"Copy Trope Model"},inspiration_wd_desc:{"zh-CN":"多题材世界观与力量体系设定库：包含清晰境界阶梯、三大不可违背法则铁律、货币资源兑换链及战力防崩红线。","en-US":"Multigenre Worldbuilding & Power Systems: clear progression tiers, unbreakable iron laws, currency/resource conversion, and power creep safeguards."},inspiration_wd_ladder:{"zh-CN":"境界进阶阶梯：","en-US":"Progression Ladder:"},inspiration_wd_power:{"zh-CN":"能力：","en-US":"Power: "},inspiration_wd_cost:{"zh-CN":"代价：","en-US":"Cost: "},inspiration_wd_ironrules:{"zh-CN":"法则铁律：","en-US":"Iron Rules:"},inspiration_wd_currency:{"zh-CN":"货币与资源：","en-US":"Currencies & Resources: "},inspiration_wd_collapsewarning:{"zh-CN":"防崩红线：","en-US":"Power Creep Warning Line: "},inspiration_wd_btn_copy:{"zh-CN":"复制世界观设定","en-US":"Copy World Setting"},inspiration_dlg_desc:{"zh-CN":"名场面金句与反AI台词设计库：精选 12 大经典高频交锋场景，提供【AI书面腔反例】与【真人网文口语台词】对照，拆解潜台词、动作节拍与语言指纹。","en-US":"Signature Dialogue & Anti-Slop Library: 12 classic confrontational scenes contrasting AI expository clichés against vivid humanized spoken dialogue, with subtext, action beats, and speech profiles."},inspiration_dlg_ai_bad:{"zh-CN":"❌ AI说明文书面腔（反例）：","en-US":"❌ AI Expository Cliche (Negative Example):"},inspiration_dlg_human_good:{"zh-CN":"✅ 顶级网文口语台词（推荐）：","en-US":"✅ Vivid Spoken Dialogue (Recommended):"},inspiration_dlg_subtext:{"zh-CN":"【潜台词拆解】","en-US":"[Subtext Breakdown]"},inspiration_dlg_actions:{"zh-CN":"【神态动作搭配】","en-US":"[Action & Facial Beats]"},inspiration_dlg_speechtip:{"zh-CN":"【语言指纹建议】","en-US":"[Speech Profile Tip]"},inspiration_dlg_btn_copy:{"zh-CN":"复制台词与动作","en-US":"Copy Dialogue & Beats"},inspiration_chr_desc